import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter="\t", quotechar='"')
        columns = next(reader, None)
        if columns is None:
            return {"columns": [], "rows": []}
        rows = list(reader)
    finally:
        csv.field_size_limit(previous_limit)

    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)
    index = 1
    while len(columns) < width:
        name = f"extra_column_{index}"
        index += 1
        if name not in used:
            columns.append(name)
            used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
